mapper.select:
/*selectMasterCmClSalesLogisTaxSumCreationList*/
/* ICOMGRDT.PROCESS_TYPE = '2' TR 일 경우 */ SELECT MAX(KEP_IRS_NAME) AS KEP_IRS_NAME , MAX(SITE_GUBUN_NAME) AS SITE_GUBUN_NAME , MAX(AGENT_IRS_NO) AS AGENT_IRS_NO , MAX(AGENT_NAME) AS AGENT_NAME , KEP_DEPT , MAX(BUYER_NM) AS BUYER_NAME , SUM(GR_AMT) AS GR_AMT , BUYER , MAX(KEP_IRS_NO) AS KEP_IRS_NO , KEP_DEPT AS KEP_DEPT_ORG , AGENT , MAX(KEP_COM_CODE) AS KEP_COM_CODE , MAX(CMP_CLOSE_FLAG) AS CMP_CLOSE_FLAG , SUM(LOGISTICS_AMT) AS LOGISTICS_AMT , #{st_from_date} AS GR_FROM_DATE , #{st_to_date} AS GR_TO_DATE , MAX(CL_MON) AS CL_MON , EXPORT_YN FROM ( SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , GR.GR_DATE AS GR_DATE , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , GR.PO_NO AS PO_NO , GR.GR_NO AS GR_NO , GR.GR_SEQ AS GR_SEQ , GR.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = GR.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN GR.LOGIS_CLOSE_DEPT IS NOT NULL THEN GR.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , GR.AGENT AS AGENT , GR.DESCRIPTION AS DESCRIPTION , GR.SPECIFICATION AS SPECIFICATION , SUBSTR(GR.GR_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , GR.NTS_SEND_FLAG AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , 'N' AS EXPORT_YN FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND GR.AGENT = CM.COM_CODE AND GR.AP_BILL_FLAG = 'Y' AND GR.AR_BILL_FLAG = 'Y' AND NVL(GR.LOGIS_BILL_FLAG,'N') = 'N' AND PODT.WAREHOUSE_CODE != 'KRKORE0668' -- 수출검수센터 제외 (SMART팀 국내/해외 세금계산서 분할용) AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE IN ('2') AND POHD.DOC_TYPE <> 'X' AND GR.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND GR.BUYER IN
#{item}
AND GR.AGENT = #{st_agent_code}
AND (GR.PO_NO LIKE #{st_po_no} || '%' OR GR.GR_NO LIKE #{st_po_no} || '%')
AND GR.CLOSE_USER_ID = #{st_ar_add_user_id}
UNION ALL
/* ICOMGRDT.PROCESS_TYPE = '3' VMI 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , GR.GR_DATE AS GR_DATE , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , GR.PO_NO AS PO_NO , GR.GR_NO AS GR_NO , GR.GR_SEQ AS GR_SEQ , GR.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = GR.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN GR.LOGIS_CLOSE_DEPT IS NOT NULL THEN GR.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , PODT.WAREHOUSE_CODE AS AGENT , GR.DESCRIPTION AS DESCRIPTION , GR.SPECIFICATION AS SPECIFICATION , SUBSTR(GR.GR_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , GR.NTS_SEND_FLAG AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , 'N' AS EXPORT_YN FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND PODT.WAREHOUSE_CODE = CM.COM_CODE /* GR.AGENT = '물류센타코드' , PODT.WAREHOUSE_CODE = '실공급사코드' */ AND GR.AP_BILL_FLAG = 'Y' AND GR.AR_BILL_FLAG = 'Y' AND NVL(GR.LOGIS_BILL_FLAG,'N') = 'N' AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE = '3' AND POHD.DOC_TYPE <> 'X' AND PODT.WAREHOUSE_CODE NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND GR.BUYER IN
#{item}
AND PODT.WAREHOUSE_CODE = #{st_agent_code} /* PODT.WAREHOUSE_CODE = '실공급사코드' */
AND (GR.PO_NO LIKE #{st_po_no} || '%' OR GR.GR_NO LIKE #{st_po_no} || '%')
AND GR.CLOSE_USER_ID = #{st_ar_add_user_id}
) X GROUP BY AGENT , KEP_DEPT , BUYER , EXPORT_YN UNION ALL
SELECT MAX(KEP_IRS_NAME) AS KEP_IRS_NAME , MAX(SITE_GUBUN_NAME) AS SITE_GUBUN_NAME , MAX(AGENT_IRS_NO) AS AGENT_IRS_NO , MAX(AGENT_NAME) AS AGENT_NAME , KEP_DEPT , MAX(BUYER_NM) AS BUYER_NAME , SUM(GR_AMT) AS GR_AMT , BUYER , MAX(KEP_IRS_NO) AS KEP_IRS_NO , KEP_DEPT AS KEP_DEPT_ORG , AGENT , MAX(KEP_COM_CODE) AS KEP_COM_CODE , MAX(CMP_CLOSE_FLAG) AS CMP_CLOSE_FLAG , SUM(LOGISTICS_AMT) AS LOGISTICS_AMT , #{st_from_date} AS GR_FROM_DATE , #{st_to_date} AS GR_TO_DATE , MAX(CL_MON) AS CL_MON , EXPORT_YN FROM ( SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , GR.GR_DATE AS GR_DATE , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , GR.PO_NO AS PO_NO , GR.GR_NO AS GR_NO , GR.GR_SEQ AS GR_SEQ , GR.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = GR.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN GR.LOGIS_CLOSE_DEPT IS NOT NULL THEN GR.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , GR.AGENT AS AGENT , GR.DESCRIPTION AS DESCRIPTION , GR.SPECIFICATION AS SPECIFICATION , SUBSTR(GR.GR_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , GR.NTS_SEND_FLAG AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , 'Y' AS EXPORT_YN FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND PODT.WAREHOUSE_CODE = 'KRKORE0668' -- 수출검수센터만 (SMART팀 국내/해외 세금계산서 분할용) AND GR.AGENT = CM.COM_CODE AND GR.AP_BILL_FLAG = 'Y' AND GR.AR_BILL_FLAG = 'Y' AND NVL(GR.LOGIS_BILL_FLAG,'N') = 'N' AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE IN ('2') AND POHD.DOC_TYPE <> 'X' AND GR.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND GR.BUYER IN
#{item}
AND GR.AGENT = #{st_agent_code}
AND (GR.PO_NO LIKE #{st_po_no} || '%' OR GR.GR_NO LIKE #{st_po_no} || '%')
AND GR.CLOSE_USER_ID = #{st_ar_add_user_id}
) Y GROUP BY AGENT , KEP_DEPT , BUYER , EXPORT_YN ORDER BY AGENT , KEP_DEPT , BUYER

/*selectMasterCmClSalesLogisTaxSumCreationList_v2*/
/* ICOMIVDT.PROCESS_TYPE = '2' TR 일 경우 */ SELECT MAX(KEP_IRS_NAME) AS KEP_IRS_NAME , MAX(SITE_GUBUN_NAME) AS SITE_GUBUN_NAME , MAX(AGENT_IRS_NO) AS AGENT_IRS_NO , MAX(AGENT_NAME) AS AGENT_NAME , KEP_DEPT , MAX(BUYER_NM) AS BUYER_NAME , SUM(INV_AMT) AS INV_AMT , BUYER , MAX(KEP_IRS_NO) AS KEP_IRS_NO , KEP_DEPT AS KEP_DEPT_ORG , AGENT , MAX(KEP_COM_CODE) AS KEP_COM_CODE , MAX(CMP_CLOSE_FLAG) AS CMP_CLOSE_FLAG , SUM(LOGISTICS_AMT) AS LOGISTICS_AMT , #{st_from_date} AS INV_FROM_DATE , #{st_to_date} AS INV_TO_DATE , MAX(CL_MON) AS CL_MON , EXPORT_YN FROM ( SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , IV.DELIVERY_DATE AS DELIVERY_DATE , ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))) AS INV_AMT , IV.PO_NO AS PO_NO , IV.INV_NO AS INV_NO , IV.INV_SEQ AS INV_SEQ , IV.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = IV.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN IV.LOGIS_CLOSE_DEPT IS NOT NULL THEN IV.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , IV.AGENT AS AGENT , IV.DESCRIPTION AS DESCRIPTION , IV.SPECIFICATION AS SPECIFICATION , SUBSTR(IV.DELIVERY_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , 'N' AS EXPORT_YN FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND IV.AGENT = CM.COM_CODE AND IV.AP_BILL_FLAG = 'Y' AND NVL(IV.LOGIS_BILL_FLAG,'N') = 'N' AND PODT.WAREHOUSE_CODE != 'KRKORE0668' -- 수출검수센터 제외 (SMART팀 국내/해외 세금계산서 분할용) AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE = '2' AND POHD.DOC_TYPE <> 'X' AND IV.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND IV.BUYER IN
#{item}
AND IV.AGENT = #{st_agent_code}
AND IV.PO_NO LIKE #{st_po_no}
AND DECODE(IV.PROCESS_TYPE,'0',(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE GR.BUYER = IV.BUYER AND GR.INV_NO = IV.INV_NO AND GR.INV_SEQ = IV.INV_SEQ AND GR.STATUS != 'D') ,(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE (GR.BUYER,GR.INV_NO,GR.INV_SEQ) = (SELECT WMS.BUYER,WMS.INV_NO,WMS.INV_SEQ FROM WMSIVDT WMS WHERE WMS.BUYER = IV.BUYER AND WMS.S_INV_NO = IV.INV_NO AND WMS.S_INV_SEQ = IV.INV_SEQ AND WMS.STATUS != 'D') AND GR.STATUS != 'D')) = #{st_ar_add_user_id}
UNION ALL
/* ICOMIVDT.PROCESS_TYPE = '3' VMI 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , IV.DELIVERY_DATE AS DELIVERY_DATE , ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))) AS INV_AMT , IV.PO_NO AS PO_NO , IV.INV_NO AS INV_NO , IV.INV_SEQ AS INV_SEQ , IV.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = IV.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN IV.LOGIS_CLOSE_DEPT IS NOT NULL THEN IV.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , PODT.WAREHOUSE_CODE AS AGENT , IV.DESCRIPTION AS DESCRIPTION , IV.SPECIFICATION AS SPECIFICATION , SUBSTR(IV.DELIVERY_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , 'N' AS EXPORT_YN FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND PODT.WAREHOUSE_CODE = CM.COM_CODE /* IV.AGENT = '물류센타코드' , PODT.WAREHOUSE_CODE = '실공급사코드' */ AND IV.AP_BILL_FLAG = 'Y' AND NVL(IV.LOGIS_BILL_FLAG,'N') = 'N' AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE = '3' AND POHD.DOC_TYPE <> 'X' AND PODT.WAREHOUSE_CODE NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND IV.BUYER IN
#{item}
AND PODT.WAREHOUSE_CODE = #{st_agent_code} /* PODT.WAREHOUSE_CODE = '실공급사코드' */
AND IV.PO_NO LIKE #{st_po_no}
AND DECODE(IV.PROCESS_TYPE,'0',(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE GR.BUYER = IV.BUYER AND GR.INV_NO = IV.INV_NO AND GR.INV_SEQ = IV.INV_SEQ AND GR.STATUS != 'D') ,(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE (GR.BUYER,GR.INV_NO,GR.INV_SEQ) = (SELECT WMS.BUYER,WMS.INV_NO,WMS.INV_SEQ FROM WMSIVDT WMS WHERE WMS.BUYER = IV.BUYER AND WMS.S_INV_NO = IV.INV_NO AND WMS.S_INV_SEQ = IV.INV_SEQ AND WMS.STATUS != 'D') AND GR.STATUS != 'D')) = #{st_ar_add_user_id}
) X GROUP BY AGENT , KEP_DEPT , BUYER , EXPORT_YN UNION ALL
SELECT MAX(KEP_IRS_NAME) AS KEP_IRS_NAME , MAX(SITE_GUBUN_NAME) AS SITE_GUBUN_NAME , MAX(AGENT_IRS_NO) AS AGENT_IRS_NO , MAX(AGENT_NAME) AS AGENT_NAME , KEP_DEPT , MAX(BUYER_NM) AS BUYER_NAME , SUM(INV_AMT) AS INV_AMT , BUYER , MAX(KEP_IRS_NO) AS KEP_IRS_NO , KEP_DEPT AS KEP_DEPT_ORG , AGENT , MAX(KEP_COM_CODE) AS KEP_COM_CODE , MAX(CMP_CLOSE_FLAG) AS CMP_CLOSE_FLAG , SUM(LOGISTICS_AMT) AS LOGISTICS_AMT , #{st_from_date} AS INV_FROM_DATE , #{st_to_date} AS INV_TO_DATE , MAX(CL_MON) AS CL_MON , EXPORT_YN FROM ( SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , IV.DELIVERY_DATE AS DELIVERY_DATE , ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))) AS INV_AMT , IV.PO_NO AS PO_NO , IV.INV_NO AS INV_NO , IV.INV_SEQ AS INV_SEQ , IV.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = IV.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN IV.LOGIS_CLOSE_DEPT IS NOT NULL THEN IV.LOGIS_CLOSE_DEPT ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , IV.AGENT AS AGENT , IV.DESCRIPTION AS DESCRIPTION , IV.SPECIFICATION AS SPECIFICATION , SUBSTR(IV.DELIVERY_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))),'01', PODT.WAREHOUSE_CODE) AS LOGISTICS_AMT , 'Y' AS EXPORT_YN FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND PODT.WAREHOUSE_CODE = 'KRKORE0668' -- 수출검수센터만 (SMART팀 국내/해외 세금계산서 분할용) AND IV.AGENT = CM.COM_CODE AND IV.AP_BILL_FLAG = 'Y' AND NVL(IV.LOGIS_BILL_FLAG,'N') = 'N' AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE = '2' AND POHD.DOC_TYPE <> 'X' AND IV.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND IV.BUYER IN
#{item}
AND IV.AGENT = #{st_agent_code}
AND IV.PO_NO LIKE #{st_po_no}
AND DECODE(IV.PROCESS_TYPE,'0',(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE GR.BUYER = IV.BUYER AND GR.INV_NO = IV.INV_NO AND GR.INV_SEQ = IV.INV_SEQ AND GR.STATUS != 'D') ,(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE (GR.BUYER,GR.INV_NO,GR.INV_SEQ) = (SELECT WMS.BUYER,WMS.INV_NO,WMS.INV_SEQ FROM WMSIVDT WMS WHERE WMS.BUYER = IV.BUYER AND WMS.S_INV_NO = IV.INV_NO AND WMS.S_INV_SEQ = IV.INV_SEQ AND WMS.STATUS != 'D') AND GR.STATUS != 'D')) = #{st_ar_add_user_id}
) Y GROUP BY AGENT , KEP_DEPT , BUYER , EXPORT_YN ORDER BY AGENT , KEP_DEPT , BUYER

