INSERT INTO KEPTARDT /* 물류비_세금계산서 */ ( TAX_BILL_NO , KEP_IRS , SITE , DEPT_CODE , STATUS , ISSUE_DATE , CUSTOMER_NAME , IRS_NO , BUYER_CODE
, TOT_SUPP_PRICE , TOT_TAX_PRICE , TOT_AMT , SUPP_PRICE , TAX_PRICE , AMT
, TAX_TYPE , BILL_TYPE , PRINT_DATE , PRINT_USER_ID , PRINT_CNT , PRINT_AVAIL_CNT , CONFIRM_FLAG , REMARK_DESCRIPTION , REMARK_SPECIFICATION , REMARK_QTY , REMARK_PRICE
, ASK_TYPE , ADD_DATE , ADD_TIME , ADD_USER_ID , CHANGE_DATE , CHANGE_TIME , CHANGE_USER_ID
, AR_CLOSE_MONTH , AR_CLOSE_REVISION , KEP_IRS_NAME , KEP_CEO_NAME_LOC , KEP_INDUSTRY_TYPE , KEP_BUSINESS_ITEMS , KEP_ADDRESS_LOC , IRS_NAME , CEO_NAME_LOC , INDUSTRY_TYPE , BUSINESS_ITEMS , ADDRESS_LOC , AR_TYPE , AGENT_CODE , EXP_FLAG ) VALUES ( #{order_no} , #{KEP_IRS_NO} , DECODE(#{BUYER}, 'KRKOLO0077', 'KK','KA') , #{dept_code} , 'C' , #{issue_date} || #{issue_last_day} , #{agent_irs_name} , #{agent_irs_no} , #{buyer_code}
, TRUNC(#{tot_supp_price}) , TRUNC(#{tot_supp_price} * 0.1) , TRUNC(#{tot_supp_price}+TRUNC(#{tot_supp_price} * 0.1)) , TRUNC(#{supp_price}) , TRUNC(#{supp_price} * 0.1) , TRUNC(#{supp_price}+TRUNC(#{supp_price} * 0.1))
, '11' /*TAX_TYPE*/ , (SELECT CM.BILL_TYPE FROM ICOMCMPY CM WHERE CM.COM_CODE = #{agent_code}) /*BILL_TYPE*/ , '' /*PRINT_DATE*/ , '' /*PRINT_USER_ID*/ , 0 /*PRINT_CNT*/ , 1 /*PRINT_AVAIL_CNT*/ , 'N' /*CONFIRM_FLAG*/ , SUBSTR(#{item_desc},0,25) , SUBSTR(#{item_desc},0,25) , 1 , TRUNC(#{tot_supp_price})
, '02' /*ASK_TYPE*/ , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id} , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id}
, #{issue_date} , #{st_close_revision} , (SELECT IRS_NAME FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_IRS_NAME */ , (SELECT CEO_NAME_LOC FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_CEO_NAME_LOC */ , (SELECT INDUSTRY_TYPE FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_INDUSTRY_TYPE */ , (SELECT BUSINESS_ITEMS FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_BUSINESS_ITEMS */ , (SELECT ADDRESS_LOC FROM KEPTIRSN WHERE SITE = 'KA' AND COM_CODE = #{KEP_COM_CODE} AND IRS_NO = #{KEP_IRS_NO} ) /* KEP_ADDRESS_LOC */ , (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* IRS_NAME */ , (SELECT CEO_NAME_LOC FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* CEO_NAME_LOC */ , (SELECT INDUSTRY_TYPE FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* INDUSTRY_TYPE */ , (SELECT BUSINESS_ITEMS FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* BUSINESS_ITEMS */ , (SELECT ADDRESS_LOC FROM V_VOC_ICOMCMPY WHERE SYS_TYPE = 'KA' AND COM_CODE = #{agent_code} AND BUSINESS_COND <> 'B') /* ADDRESS_LOC */ , '02' ,#{agent_code} ,#{exportYn} )

