UPDATE ICOMGRDT A SET LOGIS_TAX_BILL_NO = #{order_no} , LOGIS_CLOSE_DEPT = LPAD(#{dept_code},3,0) , LOGIS_COLSE_MONTH = #{issue_date} , LOGIS_CLOSE_REVISION = #{st_close_revision} , LOGIS_BILL_FLAG = 'Y' , LOGIS_RATE= (SELECT F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, GR.AGENT, 0,'02', PODT.WAREHOUSE_CODE) FROM ICOMPODT PODT, ICOMGRDT GR WHERE PODT.BUYER = GR.BUYER AND PODT.PO_NO = GR.PO_NO AND PODT.PO_SEQ = GR.PO_SEQ AND GR.BUYER = A.BUYER AND GR.GR_NO = A.GR_NO AND GR.GR_SEQ = A.GR_SEQ AND PODT.STATUS != 'D' AND GR.STATUS != 'D') , LOGIS_AMT = (SELECT F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, GR.AGENT, ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))),'01', PODT.WAREHOUSE_CODE) FROM ICOMPODT PODT, ICOMGRDT GR WHERE PODT.BUYER = GR.BUYER AND PODT.PO_NO = GR.PO_NO AND PODT.PO_SEQ = GR.PO_SEQ AND GR.BUYER = A.BUYER AND GR.GR_NO = A.GR_NO AND GR.GR_SEQ = A.GR_SEQ AND PODT.STATUS != 'D' AND GR.STATUS != 'D') , LOGIS_RATE_STATUS =(SELECT F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, GR.AGENT, 0,'03', PODT.WAREHOUSE_CODE) FROM ICOMPODT PODT, ICOMGRDT GR WHERE PODT.BUYER = GR.BUYER AND PODT.PO_NO = GR.PO_NO AND PODT.PO_SEQ = GR.PO_SEQ AND GR.BUYER = A.BUYER AND GR.GR_NO = A.GR_NO AND GR.GR_SEQ = A.GR_SEQ AND PODT.STATUS != 'D' AND GR.STATUS != 'D') WHERE NVL(LOGIS_BILL_FLAG, 'N') = 'N' AND (BUYER, GR_NO, GR_SEQ) IN ( /* ICOMGRDT.PROCESS_TYPE = '0' 직납 또는 ICOMGRDT.PROCESS_TYPE = '2' 재고 일 경우 */ SELECT GR.BUYER , GR.GR_NO , GR.GR_SEQ FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND GR.AGENT = CM.COM_CODE AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND PODT.WAREHOUSE_CODE != 'KRKORE0668' AND GR.PROCESS_TYPE = '2' AND POHD.DOC_TYPE <> 'X' AND GR.BUYER = COD.TEXT1(+) AND GR.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND GR.AGENT = #{agent_code} AND GR_DATE BETWEEN #{key_gr_from_date} AND #{key_gr_to_date} AND AP_BILL_FLAG = 'Y' AND AR_BILL_FLAG = 'Y' AND GR.STATUS <> 'D' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND GR.BUYER = #{key_buyer_code}
AND GR.CLOSE_USER_ID = #{st_ar_add_user_id}
UNION ALL
/* ICOMGRDT.PROCESS_TYPE = '3' VMI 일 경우 */ SELECT GR.BUYER , GR.GR_NO , GR.GR_SEQ FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND PODT.WAREHOUSE_CODE = CM.COM_CODE AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE = '3' AND POHD.DOC_TYPE <> 'X' AND PODT.BUYER = COD.TEXT1(+) AND PODT.WAREHOUSE_CODE = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND PODT.WAREHOUSE_CODE = #{agent_code} AND GR_DATE BETWEEN #{key_gr_from_date} AND #{key_gr_to_date} AND AP_BILL_FLAG = 'Y' AND AR_BILL_FLAG = 'Y' AND GR.STATUS <> 'D' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND GR.BUYER = #{key_buyer_code}
AND GR.CLOSE_USER_ID = #{st_ar_add_user_id}
UNION ALL
/* ICOMGRDT.PROCESS_TYPE = '1' 재고 일 경우 */ SELECT GR.BUYER , GR.GR_NO , GR.GR_SEQ FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND GR.AGENT = CM.COM_CODE AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE = '1' AND GR.AGENT NOT IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'S' AND FLAG = 'Y') AND POHD.DOC_TYPE <> 'X' AND GR.BUYER = COD.TEXT1(+) AND GR.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND GR.AGENT = #{agent_code} AND GR_DATE BETWEEN #{key_gr_from_date} AND #{key_gr_to_date} AND GR.AP_BILL_FLAG = 'Y' AND GR.BUYER IN (select text1 from ICOMCOD1 WHERE TYPE = 'HUB') AND GR.STATUS <> 'D' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND GR.BUYER = #{key_buyer_code}
AND GR.CLOSE_USER_ID = #{st_ar_add_user_id}
)

/*updateMasterCmClSalesLogisTaxSumCreation_ICOMIVDT_v2*/
UPDATE ICOMIVDT A SET LOGIS_TAX_BILL_NO = #{order_no} , LOGIS_CLOSE_DEPT = LPAD(#{dept_code},3,0) , LOGIS_COLSE_MONTH = #{issue_date} , LOGIS_CLOSE_REVISION = #{st_close_revision} , LOGIS_BILL_FLAG = 'Y' , LOGIS_RATE= (SELECT F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, IV.AGENT, 0,'02', PODT.WAREHOUSE_CODE) FROM ICOMPODT PODT, ICOMIVDT IV WHERE PODT.BUYER = IV.BUYER AND PODT.PO_NO = IV.PO_NO AND PODT.PO_SEQ = IV.PO_SEQ AND IV.BUYER = A.BUYER AND IV.INV_NO = A.INV_NO AND IV.INV_SEQ = A.INV_SEQ AND PODT.STATUS != 'D' AND IV.STATUS != 'D') , LOGIS_AMT = (SELECT F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, IV.AGENT, ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))),'01', PODT.WAREHOUSE_CODE) FROM ICOMPODT PODT, ICOMIVDT IV WHERE PODT.BUYER = IV.BUYER AND PODT.PO_NO = IV.PO_NO AND PODT.PO_SEQ = IV.PO_SEQ AND IV.BUYER = A.BUYER AND IV.INV_NO = A.INV_NO AND IV.INV_SEQ = A.INV_SEQ AND PODT.STATUS != 'D' AND IV.STATUS != 'D') , LOGIS_RATE_STATUS =(SELECT F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, IV.AGENT, 0,'03', PODT.WAREHOUSE_CODE) FROM ICOMPODT PODT, ICOMIVDT IV WHERE PODT.BUYER = IV.BUYER AND PODT.PO_NO = IV.PO_NO AND PODT.PO_SEQ = IV.PO_SEQ AND IV.BUYER = A.BUYER AND IV.INV_NO = A.INV_NO AND IV.INV_SEQ = A.INV_SEQ AND PODT.STATUS != 'D' AND IV.STATUS != 'D') WHERE NVL(LOGIS_BILL_FLAG, 'N') = 'N' AND (BUYER, INV_NO, INV_SEQ) IN ( /* ICOMIVDT.PROCESS_TYPE = '0' 직납 또는 ICOMGRDT.PROCESS_TYPE = '2' 재고 일 경우 */ SELECT IV.BUYER , IV.INV_NO , IV.INV_SEQ FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND IV.AGENT = CM.COM_CODE AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND PODT.WAREHOUSE_CODE != 'KRKORE0668' AND IV.PROCESS_TYPE = '2' AND POHD.DOC_TYPE <> 'X' AND IV.BUYER = COD.TEXT1(+) AND IV.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND IV.AGENT = #{agent_code} AND IV.DELIVERY_DATE BETWEEN #{key_inv_from_date} AND #{key_inv_to_date} AND IV.AP_BILL_FLAG = 'Y' AND IV.STATUS <> 'D' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND IV.BUYER = #{key_buyer_code}
