/*updateMasterCmClSalesLogisNotClose_v2*/
UPDATE ICOMIVDT A SET LOGIS_TAX_BILL_NO = '미마감' , LOGIS_CLOSE_DEPT = LPAD(#{dept_code},3,0) , LOGIS_COLSE_MONTH = #{issue_date} , LOGIS_CLOSE_REVISION = #{st_close_revision} , LOGIS_BILL_FLAG = 'Y' , LOGIS_RATE= 0 , LOGIS_AMT = 0 , LOGIS_RATE_STATUS ='ZZ' WHERE NVL(LOGIS_BILL_FLAG, 'N') = 'N' AND (BUYER, INV_NO, INV_SEQ) IN ( /* ICOMIVDT.PROCESS_TYPE = '0' 직납 또는 ICOMIVDT.PROCESS_TYPE = '2' 재고 일 경우 */ SELECT IV.BUYER , IV.INV_NO , IV.INV_SEQ FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND IV.AGENT = CM.COM_CODE AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE IN ('0','2') AND POHD.DOC_TYPE <> 'X' AND IV.BUYER = COD.TEXT1(+) AND IV.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND IV.AGENT = #{agent_code} AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.AP_BILL_FLAG = 'Y' AND IV.STATUS <> 'D' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND IV.BUYER = #{key_buyer_code}
AND DECODE(IV.PROCESS_TYPE,'0',(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE GR.BUYER = IV.BUYER AND GR.INV_NO = IV.INV_NO AND GR.INV_SEQ = IV.INV_SEQ AND GR.STATUS != 'D') ,(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE (GR.BUYER,GR.INV_NO,GR.INV_SEQ) = (SELECT WMS.BUYER,WMS.INV_NO,WMS.INV_SEQ FROM WMSIVDT WMS WHERE WMS.BUYER = IV.BUYER AND WMS.S_INV_NO = IV.INV_NO AND WMS.S_INV_SEQ = IV.INV_SEQ AND WMS.STATUS != 'D') AND GR.STATUS != 'D')) = #{st_ar_add_user_id}
UNION ALL
/* ICOMIVDT.PROCESS_TYPE = '3' VMI 일 경우 */ SELECT IV.BUYER , IV.INV_NO , IV.INV_SEQ FROM ICOMIVDT IV /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND PODT.WAREHOUSE_CODE = CM.COM_CODE AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE = '3' AND POHD.DOC_TYPE <> 'X' AND PODT.BUYER = COD.TEXT1(+) AND PODT.WAREHOUSE_CODE = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND PODT.WAREHOUSE_CODE = #{agent_code} AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.AP_BILL_FLAG = 'Y' AND IV.STATUS <> 'D' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND IV.BUYER = #{key_buyer_code}
AND DECODE(IV.PROCESS_TYPE,'0',(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE GR.BUYER = IV.BUYER AND GR.INV_NO = IV.INV_NO AND GR.INV_SEQ = IV.INV_SEQ AND GR.STATUS != 'D') ,(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE (GR.BUYER,GR.INV_NO,GR.INV_SEQ) = (SELECT WMS.BUYER,WMS.INV_NO,WMS.INV_SEQ FROM WMSIVDT WMS WHERE WMS.BUYER = IV.BUYER AND WMS.S_INV_NO = IV.INV_NO AND WMS.S_INV_SEQ = IV.INV_SEQ AND WMS.STATUS != 'D') AND GR.STATUS != 'D')) = #{st_ar_add_user_id}
UNION ALL
/* ICOMIVDT.PROCESS_TYPE = '1' 재고 일 경우 */ SELECT IV.BUYER , IV.INV_NO , IV.INV_SEQ FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ WHERE 1=1 AND IV.AGENT = CM.COM_CODE AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE = '1' AND IV.AGENT NOT IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'S' AND FLAG = 'Y') AND POHD.DOC_TYPE <> 'X' AND IV.BUYER = COD.TEXT1(+) AND IV.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND IV.AGENT = #{agent_code} AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.AP_BILL_FLAG = 'Y' AND IV.BUYER IN (select text1 from ICOMCOD1 WHERE TYPE = 'HUB') AND IV.STATUS <> 'D' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND IV.BUYER = #{key_buyer_code}
AND DECODE(IV.PROCESS_TYPE,'0',(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE GR.BUYER = IV.BUYER AND GR.INV_NO = IV.INV_NO AND GR.INV_SEQ = IV.INV_SEQ AND GR.STATUS != 'D') ,(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE (GR.BUYER,GR.INV_NO,GR.INV_SEQ) = (SELECT WMS.BUYER,WMS.INV_NO,WMS.INV_SEQ FROM WMSIVDT WMS WHERE WMS.BUYER = IV.BUYER AND WMS.S_INV_NO = IV.INV_NO AND WMS.S_INV_SEQ = IV.INV_SEQ AND WMS.STATUS != 'D') AND GR.STATUS != 'D')) = #{st_ar_add_user_id}
)
